package com.ukkera.pos.inventory.store

import com.ukkera.pos.database.StoredBytes
import com.ukkera.pos.inventory.ReceiptValueOrigin
import com.ukkera.pos.inventory.StockMovementReason
import com.ukkera.pos.security.PayloadDigest
import com.ukkera.pos.types.Revision
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonPrimitive
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertIs
import kotlin.test.assertNull
import kotlin.test.assertTrue

/**
 * Literal receipt-v1 compatibility controls for the private ReceiptWire extraction. Expected
 * bytes below are fixed independent wire literals, NEVER generated by a codec under test.
 * These are authored controls until executed; source identity is not runtime verification.
 */
class InventoryRetailLegacyWireCompatibilityTest {
    private val f = ReceiptFixtures

    @Test fun legacyGenesisAndNullableAndPopulatedReceiveRequestsHaveLiteralGoldenBytes() {
        assertEquals(LEGACY_GENESIS_REQUEST, InventoryReceiptCommandCodec.genesisRequest().copyBytes().decodeToString())
        assertEquals(bytes(LEGACY_GENESIS_REQUEST), InventoryReceiptCommandCodec.normalizeGenesis(bytes(LEGACY_GENESIS_REQUEST)))
        val populated = f.request()
        val nullable = populated.copy(lotId = null, expiresAtEpochMillis = null)
        assertEquals(LEGACY_POPULATED_RECEIVE_REQUEST, InventoryReceiptCommandCodec.encode(populated).copyBytes().decodeToString())
        assertEquals(LEGACY_NULLABLE_RECEIVE_REQUEST, InventoryReceiptCommandCodec.encode(nullable).copyBytes().decodeToString())
        assertEquals(populated, InventoryReceiptCommandCodec.decode(bytes(LEGACY_POPULATED_RECEIVE_REQUEST)))
        assertEquals(nullable, InventoryReceiptCommandCodec.decode(bytes(LEGACY_NULLABLE_RECEIVE_REQUEST)))
        assertEquals(bytes(LEGACY_POPULATED_RECEIVE_REQUEST), InventoryReceiptCommandCodec.normalizeReceive(bytes(LEGACY_POPULATED_RECEIVE_REQUEST)))
    }

    @Test fun legacyGenesisAndTwoSourceCompanionsHaveLiteralGoldenBytesAndSemantics() {
        val genesis = InventoryReceiptCompanion(f.scope, f.scope.branchId, Revision(0), PayloadDigest("0".repeat(64)),
            InventoryReceiptProducer(f.op(999), InventoryReceiptStoreProfile.GENESIS_COMMAND, f.actor, PayloadDigest("1".repeat(64))),
            null, emptyList(), emptyList())
        val received = twoSources()
        assertEquals(LEGACY_GENESIS_COMPANION, InventoryReceiptCompanionCodec.encode(genesis).copyBytes().decodeToString())
        assertEquals(LEGACY_TWO_SOURCE_COMPANION, InventoryReceiptCompanionCodec.encode(received).copyBytes().decodeToString())
        val decodedGenesis = InventoryReceiptCompanionCodec.decode(bytes(LEGACY_GENESIS_COMPANION), companionBinding(genesis))
        val decoded = InventoryReceiptCompanionCodec.decode(bytes(LEGACY_TWO_SOURCE_COMPANION), companionBinding(received))
        assertNull(decodedGenesis.previous)
        assertTrue(decodedGenesis.sources.isEmpty() && decodedGenesis.effects.isEmpty())
        assertEquals(received.sources, decoded.sources)
        assertEquals(received.effects, decoded.effects)
        assertEquals(received.previous, decoded.previous)
        assertEquals(received.producer, decoded.producer)
        assertIs<InventoryReceiptPostedEffect.Valuation>(decoded.effects[0])
        assertIs<InventoryReceiptPostedEffect.Movement>(decoded.effects[1])
        assertEquals(bytes(LEGACY_TWO_SOURCE_COMPANION), InventoryReceiptCompanionCodec.encode(decoded))
    }

    @Test fun legacyGenesisAndReceivedResultsHaveLiteralGoldenBytes() {
        val genesis = InventoryReceiptResult(InventoryReceiptResultKind.GENESIS, f.scope, f.op(999), Revision(0), null,
            PayloadDigest("0".repeat(64)), PayloadDigest("5".repeat(64)))
        val received = InventoryReceiptResult(InventoryReceiptResultKind.RECEIVED, f.scope, f.op(1_002), Revision(2), f.id(102),
            PayloadDigest("4".repeat(64)), PayloadDigest("6".repeat(64)))
        assertEquals(LEGACY_GENESIS_RESULT, InventoryReceiptResultCodec.encode(genesis).copyBytes().decodeToString())
        assertEquals(LEGACY_RECEIVED_RESULT, InventoryReceiptResultCodec.encode(received).copyBytes().decodeToString())
        assertEquals(genesis, InventoryReceiptResultCodec.decode(bytes(LEGACY_GENESIS_RESULT)))
        assertEquals(received, InventoryReceiptResultCodec.decode(bytes(LEGACY_RECEIVED_RESULT)))
    }

    @Test fun legacyDefaultEpochMoneyOwnershipCustodyAndSealedSubtypeFailuresAreUnchanged() {
        legacyFailure(InventoryReceiptStoreFailure.NON_CANONICAL) { InventoryReceiptCommandCodec.normalizeGenesis(bytes("{}")) }
        legacyFailure(InventoryReceiptStoreFailure.INCONSISTENT_STATE) {
            InventoryReceiptCommandCodec.decode(bytes(jsonEdit(LEGACY_POPULATED_RECEIVE_REQUEST, listOf("expiresAtEpochMillis"), JsonPrimitive("01"))))
        }
        legacyFailure(InventoryReceiptStoreFailure.MALFORMED) {
            InventoryReceiptCommandCodec.decode(bytes(jsonEdit(LEGACY_POPULATED_RECEIVE_REQUEST, listOf("originalValue", "minor"), JsonPrimitive("01"))))
        }
        val binding = companionBinding(twoSources())
        for (path in listOf(listOf("sources", "0", "position", "pool", "ownership"), listOf("sources", "0", "position", "custody"))) {
            legacyFailure(InventoryReceiptStoreFailure.UNSUPPORTED_STATE) {
                InventoryReceiptCompanionCodec.decode(bytes(jsonEdit(LEGACY_TWO_SOURCE_COMPANION, path, JsonPrimitive("UNKNOWN"))), binding)
            }
        }
        legacyFailure(InventoryReceiptStoreFailure.MALFORMED) {
            InventoryReceiptCompanionCodec.decode(bytes(jsonEdit(LEGACY_TWO_SOURCE_COMPANION, listOf("effects", "0", "type"),
                JsonPrimitive("UNKNOWN"))), binding)
        }
        legacyFailure(InventoryReceiptStoreFailure.UNSUPPORTED_VERSION) {
            InventoryReceiptCompanionCodec.decode(bytes(jsonEdit(LEGACY_TWO_SOURCE_COMPANION, listOf("schemaVersion"), JsonPrimitive(2))), binding)
        }
    }

    @Test fun exactLegacyScannerDepthSixteenAndArrayThirtyTwoTwinsRemainUnchanged() {
        val depth16 = "{\"x\":".repeat(15) + "{}" + "}".repeat(15)
        val depth17 = "{\"x\":".repeat(16) + "{}" + "}".repeat(16)
        val array32 = "[" + List(32) { "0" }.joinToString(",") + "]"
        val array33 = "[" + List(33) { "0" }.joinToString(",") + "]"
        for (good in listOf(depth16, array32)) {
            assertEquals(good, scan(good).toString())
            // The scanner admits this size; the legacy companion serializer then rejects its
            // unknown shape. The next size must instead fail in the scanner BEFORE restoration.
            legacyFailure(InventoryReceiptStoreFailure.MALFORMED) {
                InventoryReceiptCompanionCodec.decode(bytes(good), companionBinding(twoSources()))
            }
        }
        for (bad in listOf(depth17, array33)) {
            legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) { scan(bad) }
            legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) {
                InventoryReceiptCompanionCodec.decode(bytes(bad), companionBinding(twoSources()))
            }
        }
    }

    @Test fun exactLegacyContainerThousandTwentyFourBoundaryIsNotMaskedByArrayOrRequestCaps() {
        // Small OBJECT children: 1 outer object + N children, shallow depth, no arrays.
        val good = "{" + List(1_023) { "\"n$it\":{}" }.joinToString(",") + "}"
        val bad = "{" + List(1_024) { "\"n$it\":{}" }.joinToString(",") + "}"
        assertTrue(good.encodeToByteArray().size > InventoryReceiptStoreProfile.MAX_REQUEST_BYTES)
        assertTrue(bad.encodeToByteArray().size < InventoryReceiptStoreProfile.MAX_ROW_BYTES)
        assertEquals(good, scan(good).toString())
        legacyFailure(InventoryReceiptStoreFailure.MALFORMED) {
            InventoryReceiptCompanionCodec.decode(bytes(good), companionBinding(twoSources()))
        }
        legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) { scan(bad) }
        legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) {
            InventoryReceiptCompanionCodec.decode(bytes(bad), companionBinding(twoSources()))
        }
    }

    @Test fun legacyWireBodyByteCapsAndUtf8RemainExactWithoutBypassingStoredBytes() {
        for (maximum in listOf(InventoryReceiptStoreProfile.MAX_REQUEST_BYTES, InventoryReceiptStoreProfile.MAX_RESULT_BYTES,
            InventoryReceiptStoreProfile.MAX_ROW_BYTES)) {
            val value: JsonElement = JsonPrimitive("x".repeat(maximum - 2))
            val encoded = encodeReceiptBody(value, JsonElement.serializer(), maximum)
            assertEquals(maximum, encoded.size)
            assertEquals(value, decodeReceiptBody(encoded, JsonElement.serializer(), maximum))
            legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) {
                encodeReceiptBody(JsonPrimitive("x".repeat(maximum - 1)), JsonElement.serializer(), maximum)
            }
            if (maximum < InventoryReceiptStoreProfile.MAX_ROW_BYTES) {
                legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) {
                    decodeReceiptBody(bytes(" ".repeat(maximum + 1)), JsonElement.serializer(), maximum)
                }
            } else {
                // Kernel constructor owns row cap+1; it cannot be delivered to an adapter decoder.
                val failure = assertFailsWith<IllegalArgumentException> { bytes(" ".repeat(maximum + 1)) }
                assertTrue(failure !is InventoryReceiptStoreRejected)
            }
        }
        for (raw in listOf(byteArrayOf(0xc3.toByte(), 0x28), byteArrayOf(0xed.toByte(), 0xa0.toByte(), 0x80.toByte()))) {
            legacyFailure(InventoryReceiptStoreFailure.MALFORMED) {
                InventoryReceiptCompanionCodec.decode(StoredBytes(raw), companionBinding(twoSources()))
            }
        }
    }

    @Test fun escapedContainerCharactersAndExactMultibyteBoundDoNotChangeLegacyScannerSemantics() {
        val escaped: JsonElement = JsonPrimitive("[".repeat(1_025) + "{".repeat(1_025) + ",".repeat(33) + "\"\\")
        val encoded = encodeReceiptBody(escaped, JsonElement.serializer(), InventoryReceiptStoreProfile.MAX_ROW_BYTES)
        assertEquals(escaped, scan(encoded.copyBytes().decodeToString()))
        // 21,844 three-byte characters + two ASCII characters + two JSON quotes = 65,536.
        val multibyte: JsonElement = JsonPrimitive("\u0800".repeat(21_844) + "aa")
        val exact = encodeReceiptBody(multibyte, JsonElement.serializer(), InventoryReceiptStoreProfile.MAX_ROW_BYTES)
        assertEquals(65_536, exact.size)
        assertEquals(multibyte, decodeReceiptBody(exact, JsonElement.serializer(), InventoryReceiptStoreProfile.MAX_ROW_BYTES))
        legacyFailure(InventoryReceiptStoreFailure.TOO_LARGE) {
            encodeReceiptBody(JsonPrimitive("\u0800".repeat(21_844) + "aaa"), JsonElement.serializer(), InventoryReceiptStoreProfile.MAX_ROW_BYTES)
        }
    }

    private fun legacyFailure(expected: InventoryReceiptStoreFailure, block: () -> Unit): InventoryReceiptStoreRejected =
        receiptFailure(expected, block).also { assertNull(it.cause) }

    private fun scan(text: String): JsonElement =
        decodeReceiptBody(bytes(text), JsonElement.serializer(), InventoryReceiptStoreProfile.MAX_ROW_BYTES)

    private fun bytes(text: String): StoredBytes = StoredBytes(text.encodeToByteArray())

    private fun twoSources(): InventoryReceiptCompanion {
        val sources = (1..2).map { n ->
            val request = f.request(n)
            InventoryReceiptSourceBinding(request.receiptId, f.op(1_000 + n), request.origin, request.toReceipt(f.scope).position,
                request.quantity, request.originalValue, request.expiresAtEpochMillis)
        }
        val source = sources.last()
        val effects = listOf(
            InventoryReceiptPostedEffect.Valuation(source.position.pool, Revision(1), Revision(2), source.receiptId, source.quantity,
                source.originalValue, ReceiptValueOrigin.PURCHASE, source.quantity, source.originalValue, source.originalValue),
            InventoryReceiptPostedEffect.Movement(source.receiptId, source.position, source.quantity, StockMovementReason.RECEIPT, null))
        return InventoryReceiptCompanion(f.scope, f.scope.branchId, Revision(2), PayloadDigest("4".repeat(64)),
            InventoryReceiptProducer(f.op(1_002), InventoryReceiptStoreProfile.RECEIVE_COMMAND, f.actor, PayloadDigest("1".repeat(64))),
            InventoryReceiptPreviousPair(Revision(1), f.op(1_001), PayloadDigest("2".repeat(64)), PayloadDigest("3".repeat(64))), sources, effects)
    }
}

